-- Additional APIs. Every SECURITY DEFINER operation explicitly validates its caller.
create function public.my_list_ids() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(id),'[]') from public.lists where owner_id=auth.uid() or id in(select list_id from public.list_members where user_id=auth.uid() and status='accepted')$$;
create function public.pending_invites() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('list_id',l.id,'name',l.name,'role',m.role)),'[]') from public.list_members m join public.lists l on l.id=m.list_id where m.user_id=auth.uid() and m.status='pending'$$;
create function public.profile_connections(uid uuid,mode text) returns jsonb language sql stable security definer set search_path='' as $$select case when private.profile_access(uid) then coalesce((select jsonb_agg(to_jsonb(p)) from public.profiles p where p.id in(select followed_id from public.follows where follower_id=uid and mode='following' union select follower_id from public.follows where followed_id=uid and mode='followers' union select case when sender_id=uid then recipient_id else sender_id end from public.friendships where (sender_id=uid or recipient_id=uid) and status='accepted' and mode='friends')),'[]') else '[]'::jsonb end$$;
create function public.activity_feed(mode text default 'all',before_time timestamptz default null,before_id uuid default null) returns jsonb language sql stable security invoker set search_path='' as $$select coalesce(jsonb_agg(to_jsonb(z)),'[]') from (select * from (select r.id,r.user_id,r.place_id,r.created_at,'review'::text entry_type,r.rating,r.comment,r.visibility,null::date visited_on,r.updated_at,r.hidden,jsonb_build_object('id',p.id,'display_name',p.display_name,'username',p.username) profiles,jsonb_build_object('id',l.id,'name',l.name,'category',l.category) places,coalesce((select jsonb_agg(jsonb_build_object('id',ph.id,'path',ph.path,'thumbnail_path',ph.thumbnail_path)) from public.review_photos ph where ph.review_id=r.id),'[]') review_photos,coalesce((select jsonb_agg(jsonb_build_object('user_id',lk.user_id)) from public.likes lk where lk.review_id=r.id),'[]') likes from public.reviews r join public.profiles p on p.id=r.user_id join public.places l on l.id=r.place_id where not r.hidden and not r.archived union all select md5(v.user_id::text||v.place_id::text)::uuid,v.user_id,v.place_id,v.created_at,'visit'::text,null::int,null::text,v.visibility,v.visited_on,v.created_at,false,jsonb_build_object('id',p.id,'display_name',p.display_name,'username',p.username),jsonb_build_object('id',l.id,'name',l.name,'category',l.category),'[]'::jsonb,'[]'::jsonb from public.visits v join public.profiles p on p.id=v.user_id join public.places l on l.id=v.place_id where v.shared) x where (before_time is null or (x.created_at,x.id)<(before_time,before_id)) and ((mode in ('all','friends') and private.is_friend(x.user_id)) or (mode in ('all','following') and exists(select 1 from public.follows where follower_id=auth.uid() and followed_id=x.user_id))) order by x.created_at desc,x.id desc limit 20) z$$;
create function private.limit_write() returns trigger language plpgsql security definer set search_path='' as $$begin if auth.uid() is not null then perform private.check_rate(TG_TABLE_NAME,case when TG_TABLE_NAME in ('reviews','reports','corrections') then 10 else 60 end);end if;return new;end$$;
do $$declare t text;begin foreach t in array array['reviews','likes','follows','saved_places','want_places','lists','list_places','reports','corrections'] loop execute format('create trigger rate_%I before insert on public.%I for each row execute function private.limit_write()',t,t);end loop;end$$;
create function private.merge_places(duplicate uuid,canonical uuid) returns void language plpgsql security definer set search_path='' as $$begin if duplicate=canonical or not exists(select 1 from public.places where id=canonical and merged_into is null) or not exists(select 1 from public.places where id=duplicate and merged_into is null) then raise exception 'Locales de fusión inválidos';end if;perform 1 from public.places where id in(duplicate,canonical) order by id for update;
 -- Canonical review remains active. Conflicting duplicate reviews are archived, never erased.
 update public.reviews d set archived=true where d.place_id=duplicate and exists(select 1 from public.reviews c where c.place_id=canonical and c.user_id=d.user_id and not c.archived);
 update public.reviews set place_id=canonical where place_id=duplicate;
 insert into public.saved_places(user_id,place_id,created_at) select user_id,canonical,created_at from public.saved_places where place_id=duplicate on conflict do nothing;delete from public.saved_places where place_id=duplicate;
 insert into public.want_places(user_id,place_id,created_at) select user_id,canonical,created_at from public.want_places where place_id=duplicate on conflict do nothing;delete from public.want_places where place_id=duplicate;
 insert into public.visits(user_id,place_id,visited_on,visibility,shared,created_at) select user_id,canonical,visited_on,visibility,shared,created_at from public.visits where place_id=duplicate on conflict do nothing;delete from public.visits where place_id=duplicate;
 insert into public.list_places(list_id,place_id,added_by,created_at) select list_id,canonical,added_by,created_at from public.list_places where place_id=duplicate on conflict do nothing;delete from public.list_places where place_id=duplicate;
 update public.place_sources set place_id=canonical where place_id=duplicate;update public.places set merged_into=canonical where id=duplicate;end$$;
create function public.moderation_queue() returns jsonb language plpgsql stable security definer set search_path='' as $$begin if not private.is_moderator() then raise exception 'Acceso restringido';end if;return jsonb_build_object('corrections',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from public.corrections where status='pending' order by created_at limit 100)x),'[]'),'reports',coalesce((select jsonb_agg(to_jsonb(x)) from(select r.*,v.comment,v.hidden,ph.thumbnail_path from public.reports r left join public.review_photos ph on ph.id=r.photo_id left join public.reviews v on v.id=coalesce(r.review_id,ph.review_id) where r.status='pending' order by r.created_at limit 100)x),'[]'),'hidden_photos',coalesce((select jsonb_agg(to_jsonb(ph)) from public.review_photos ph where hidden),'[]'),'hidden',coalesce((select jsonb_agg(to_jsonb(x)) from(select id,comment from public.reviews where hidden order by updated_at desc limit 100)x),'[]'));end$$;
create function public.moderate(target uuid,action text,reason text) returns void language plpgsql security definer set search_path='' as $$declare c public.corrections;r public.reports;rid uuid;k text;begin if not private.is_moderator() then raise exception 'Acceso restringido';end if;perform private.check_rate('moderation',60);if length(trim(reason)) not between 5 and 1000 then raise exception 'Motivo requerido';end if;
 if action in ('approve_correction','reject_correction') then select * into c from public.corrections where id=target and status='pending' for update;if c.id is null then raise exception 'Propuesta no disponible';end if;if action='approve_correction' then if c.fields ? 'duplicate_of' then if (select count(*) from jsonb_object_keys(c.fields))<>1 then raise exception 'Separá la fusión de otras correcciones';end if;perform private.merge_places(c.place_id,(c.fields->>'duplicate_of')::uuid);else for k in select jsonb_object_keys(c.fields) loop if k not in ('address','opening_hours','phone','website','instagram','category','closed') then raise exception 'Campo no permitido';end if;if k='category' and not exists(select 1 from public.categories where id=c.fields->>'category') then raise exception 'Categoría inválida';end if;if length(c.fields->>k)>500 then raise exception 'Dato demasiado largo';end if;end loop;update public.places set address=case when c.fields?'address' then c.fields->>'address' else address end,opening_hours=case when c.fields?'opening_hours' then c.fields->>'opening_hours' else opening_hours end,phone=case when c.fields?'phone' then c.fields->>'phone' else phone end,website=case when c.fields?'website' then c.fields->>'website' else website end,instagram=case when c.fields?'instagram' then c.fields->>'instagram' else instagram end,category=case when c.fields?'category' then c.fields->>'category' else category end,closed=case when c.fields?'closed' then (c.fields->>'closed')::boolean else closed end where id=c.place_id;insert into public.place_overrides(place_id,fields) values(c.place_id,c.fields) on conflict(place_id) do update set fields=public.place_overrides.fields||excluded.fields,updated_at=now();end if;end if;update public.corrections set status=case when action='approve_correction' then 'approved' else 'rejected' end where id=target;
 elsif action in ('hide_reported','reject_report') then select * into r from public.reports where id=target and status='pending' for update;if r.id is null then raise exception 'Reporte no disponible';end if;if action='hide_reported' then if r.photo_id is not null then update public.review_photos set hidden=true where id=r.photo_id;else update public.reviews set hidden=true where id=r.review_id;end if;end if;update public.reports set status=case when action='hide_reported' then 'resolved' else 'rejected' end where id=target;
 elsif action='restore_photo' then update public.review_photos set hidden=false where id=target;elsif action='restore_review' then update public.reviews set hidden=false where id=target;
 else raise exception 'Acción inválida';end if;insert into public.moderation_audit(moderator_id,action,target_id,reason) values(auth.uid(),action,target,reason);end$$;
create function public.photo_gc_batch() returns table(path text) language sql security definer set search_path='' as $$select path from private.photo_gc order by queued_at limit 200$$;
create function public.photo_gc_done(paths text[]) returns void language sql security definer set search_path='' as $$delete from private.photo_gc where path=any(paths)$$;
revoke execute on function public.my_list_ids(),public.pending_invites(),public.profile_connections(uuid,text),public.activity_feed(text,timestamptz,uuid),public.moderation_queue(),public.moderate(uuid,text,text),public.photo_gc_batch(),public.photo_gc_done(text[]) from public,anon,authenticated;
revoke execute on function private.limit_write(),private.merge_places(uuid,uuid) from public,anon,authenticated;
grant execute on function public.my_list_ids(),public.pending_invites(),public.activity_feed(text,timestamptz,uuid),public.moderation_queue(),public.moderate(uuid,text,text) to authenticated;
grant execute on function public.profile_connections(uuid,text) to anon,authenticated;
grant execute on function public.photo_gc_batch(),public.photo_gc_done(text[]) to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('avatars','avatars',false,5242880,array['image/jpeg','image/png','image/webp']);
create policy avatar_read on storage.objects for select using(bucket_id='avatars' and exists(select 1 from public.profiles where avatar_path=name));
